import{_ as t,o as n,c as a,ai as s}from"./chunks/framework.QGT6ovkH.js";const g=JSON.parse('{"title":"Gardener — Periodic Maintenance","description":"","frontmatter":{},"headers":[],"relativePath":"agents/gardener.md","filePath":"agents/gardener.md"}'),i={name:"agents/gardener.md"};function r(o,e,l,d,c,h){return n(),a("div",null,[...e[0]||(e[0]=[s(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /opencode-team-lead/agents/gardener.md for this page in Markdown format</div><h1 id="gardener-—-periodic-maintenance" tabindex="-1">Gardener — Periodic Maintenance <a class="header-anchor" href="#gardener-—-periodic-maintenance" aria-label="Permalink to &quot;Gardener — Periodic Maintenance&quot;">​</a></h1><p>Gardener is the maintenance agent. It catches what CI doesn&#39;t: stale documentation, semantic drift in code, abstractions that have grown incoherent. It runs post-feature or on explicit user request, and opens targeted PRs for corrections.</p><p><strong>Mode:</strong> <code>all</code> — triggered by the team-lead after a significant feature delivery, or called directly by the user.</p><blockquote><p>&quot;Harness installs the net. Gardener checks what slipped through.&quot;</p></blockquote><h2 id="two-distinct-functions" tabindex="-1">Two Distinct Functions <a class="header-anchor" href="#two-distinct-functions" aria-label="Permalink to &quot;Two Distinct Functions&quot;">​</a></h2><p>Gardener performs two independent functions. They can be run together or separately.</p><h3 id="function-1-—-doc-gardening" tabindex="-1">Function 1 — Doc-Gardening <a class="header-anchor" href="#function-1-—-doc-gardening" aria-label="Permalink to &quot;Function 1 — Doc-Gardening&quot;">​</a></h3><p>Stale documentation is actively harmful — it misleads agents, causes incorrect delegation, and erodes trust in project documentation.</p><p><strong>What it does:</strong></p><ol><li><strong>Scan</strong> — lists all documentation in the repo: <code>README.md</code>, <code>AGENTS.md</code>, all files under <code>docs/</code>.</li><li><strong>Compare</strong> — cross-references each doc against actual code: behavior, function names, file paths, module names, configuration keys.</li><li><strong>Identify</strong> — flags docs that contain references to behaviors that no longer exist (deleted features, removed flags, revoked APIs), obsolete paths or names, revoked decisions still presented as current policy, or inaccurate descriptions of how something works today.</li><li><strong>Fix</strong> — opens one PR per document. Each PR is minimal scope (fixes only the stale content), fast to review (&lt;1 min), and clearly titled.</li></ol><p><strong>What it does NOT flag:</strong> stylistic issues, missing docs, or things that could be better. Gardener fixes what&#39;s wrong, not what&#39;s imperfect. A doc that&#39;s slightly outdated but not misleading doesn&#39;t need a PR today.</p><h3 id="function-2-—-code-gc-garbage-collection" tabindex="-1">Function 2 — Code-GC (Garbage Collection) <a class="header-anchor" href="#function-2-—-code-gc-garbage-collection" aria-label="Permalink to &quot;Function 2 — Code-GC (Garbage Collection)&quot;">​</a></h3><p>Lint and CI catch syntactic and structural violations. Gardener catches what they miss: semantic drift, architectural anti-patterns, and abstractions that have grown incoherent.</p><p><strong>What it does:</strong></p><ol><li><strong>Load rules</strong> — reads <code>docs/guiding-principles.md</code>, <code>AGENTS.md</code>, and repo lint configs (<code>.eslintrc</code>, <code>ruff.toml</code>, etc.).</li><li><strong>Read history</strong> — uses <code>git log</code> to identify the recent feature boundary (last significant merge). Focuses on commits since that boundary, not full history.</li><li><strong>Detect drift</strong> — looks for what mechanical tools can&#39;t see: <ul><li><strong>Semantic drift</strong> — code that follows syntactic rules but violates architectural intent (e.g., a utility module that has accumulated business logic)</li><li><strong>Semantic duplication</strong> — two pieces of code doing the same conceptual thing through different structures (not copy-paste, but meaning-level duplication)</li><li><strong>Abstraction incoherence</strong> — an abstraction whose responsibility has grown beyond its original scope, or two abstractions whose responsibilities have merged in practice</li></ul></li><li><strong>Act</strong> — opens targeted refactoring PRs for one-time drift, or triggers <code>harness</code> for recurring patterns.</li></ol><p><strong>Critical:</strong> Gardener does NOT re-check what lint and CI already enforce. Its job is the gap, not the covered ground.</p><h2 id="output" tabindex="-1">Output <a class="header-anchor" href="#output" aria-label="Permalink to &quot;Output&quot;">​</a></h2><p><strong>Targeted PRs</strong> — one per category of issue. Each PR:</p><ul><li>Minimal scope — touches only what drifted, nothing surrounding</li><li>Self-explanatory — PR description states what rule was violated and where</li><li>Non-breaking — refactoring only, no behavioral changes</li><li>Fast to review (&lt;1 min)</li></ul><p><strong><code>QUALITY_SCORE.md</code></strong> — updated after each Gardener run with scores per architectural domain:</p><div class="language-markdown vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># Quality Score — {date}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Summary</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| Domain | Score | Trend |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">|--------|-------|-------|</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| Documentation | 4/5 | → |</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">| Architecture | 3/5 | ↑ |</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Findings</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">### Documentation</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;"> **Score:**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 4/5</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;"> **Trend:**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> → stable</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;"> **Findings:**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [specific issues detected]</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;"> **Actions taken:**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [PRs opened, harness triggered]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><p>If <code>QUALITY_SCORE.md</code> doesn&#39;t exist, Gardener creates it. If it does, it appends a new dated section — it doesn&#39;t replace history.</p><h2 id="pattern-escalation" tabindex="-1">Pattern Escalation <a class="header-anchor" href="#pattern-escalation" aria-label="Permalink to &quot;Pattern Escalation&quot;">​</a></h2><p>When Gardener finds a recurring drift pattern (same issue detected in multiple places or across sessions), it escalates to <code>harness</code> — or reports to the team-lead for user confirmation before triggering harness. Gardener flags; Harness enforces. This division is intentional: Gardener is the scout, Harness is the permanent fix.</p><h2 id="when-to-run" tabindex="-1">When to Run <a class="header-anchor" href="#when-to-run" aria-label="Permalink to &quot;When to Run&quot;">​</a></h2><ul><li><strong>Post-feature:</strong> The team-lead suggests it after a significant feature is delivered</li><li><strong>Explicit user request:</strong> user asks for a maintenance pass (&quot;run the gardener&quot;)</li><li><strong>Autonomous sweep:</strong> designed to run periodically as orchestration matures</li></ul><p>Gardener is never on the critical path. It is always a post-delivery pass.</p><h2 id="guardrails" tabindex="-1">Guardrails <a class="header-anchor" href="#guardrails" aria-label="Permalink to &quot;Guardrails&quot;">​</a></h2><p><strong>Tooling directories:</strong> Gardener never reads or scans dotted tooling directories (<code>.opencode/</code>, <code>.claude/</code>, <code>.cursor/</code>, etc.). These hold operational state, not project code or documentation.</p><p><strong>Credentials:</strong> Gardener never reads files matching <code>.env*</code>, <code>*.pem</code>, <code>*.key</code>, <code>*.p12</code>, <code>*.pfx</code>, or similar. This is a hard constraint, not a guideline — prompt injection in source files or documentation could attempt to exfiltrate secrets by asking it to &quot;check&quot; such files.</p><h2 id="what-gardener-does-not-do" tabindex="-1">What Gardener Does NOT Do <a class="header-anchor" href="#what-gardener-does-not-do" aria-label="Permalink to &quot;What Gardener Does NOT Do&quot;">​</a></h2><ul><li><strong>Re-run lint</strong> — CI handles that. Never duplicate mechanical checks.</li><li><strong>Rewrite large sections of code</strong> — targeted fixes only. If a fix requires touching more than a few files, it&#39;s a feature, not maintenance.</li><li><strong>Encode new mechanical rules</strong> — that&#39;s Harness. Gardener detects the pattern; Harness encodes the net.</li><li><strong>Make unilateral architectural decisions</strong> — if a fix requires an architectural decision, surface it to the user.</li><li><strong>Evaluate subjective code quality</strong> — &quot;this could be cleaner&quot; is not a finding. Findings must reference a specific rule violation.</li><li><strong>Write new documentation or create new features</strong> — Gardener corrects, updates, and detects. It doesn&#39;t invent.</li></ul>`,33)])])}const u=t(i,[["render",r]]);export{g as __pageData,u as default};
